template <typename T>
constexpr T square(T x) { return x * x; }

int main() {
  constexpr int sq_4 = square<int>(4); // Compile-time calculation
  int sq_5 = square<int>(5); // Compile-time if possible, otherwise runtime
  double sq_6_5 = square<double>(6.5); // Compile-time if possible, otherwise runtime
  //The compiler may optimize away the runtime calculation if the argument is a constant expression
  std::cout << sq_4 << ' ' << sq_5 << ' ' << sq_6_5 << '\n';
  return 0;
}
